fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let native=fs::read_to_string(format!("{R}/native.rs")).unwrap();let fixed=native.replace("native/libraries-","native-fixed/libraries-");assert_ne!(native,fixed);fs::write(format!("{R}/native-fixed.rs"),fixed).unwrap();let mut plan:Value=serde_json::from_slice(&fs::read(format!("{R}/build-plan.json")).unwrap()).unwrap();let mut pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(format!("{R}/build-pins.json")).unwrap()).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}
let log=fs::read_to_string(format!("{R}/native/core-off/stderr.log")).unwrap();let prefix="Running unittests src/lib.rs (";let line=log.lines().find(|l|l.trim_start().starts_with(prefix)).unwrap().trim_start();let binary=line.strip_prefix(prefix).unwrap().strip_suffix(')').unwrap();assert!(!Path::new(&format!("{R}/native/core-on")).exists());let failed=fs::read_to_string(format!("{R}/native/core-off/stdout.log")).unwrap();assert!(failed.contains("127 passed; 2 failed"));let mut steps=Vec::new();for name in["borrowed_signed_g2_generator_oracle_tails_and_reuse","owned_g2_prefix_generator_oracle_tails_and_reuse"]{let qualified=format!("msm::caller_probe::tests::{name}");steps.push(json!({"kind":"command","name":format!("repair-off-{name}"),"argv":[binary,&qualified,"--exact","--test-threads=1"],"required_tests":[qualified],"environment":plan["steps"][0]["environment"],"unfiltered":false,"timeout_seconds":600}));}
steps.extend(plan["steps"].as_array().unwrap().iter().skip(1).cloned());for step in&mut steps{for key in["ZOPRO_CPU_DIRECT","ZOPRO_CPU_CANONICAL_BATCH","ZOPRO_CPU_VECTOR_INVERSE","ZOPRO_CPU_G2_PREFIX_RECORDS","ZOPRO_CPU_PACKED"]{step["environment"][key]=json!("1");}step["environment"]["ZOPRO_CPU_G1_SCRATCH_STORE"]=json!("2");for arg in step["argv"].as_array_mut().unwrap(){if *arg==format!("{R}/native-helper"){*arg=json!(format!("{R}/native-fixed-helper"));}}}
for p in[format!("{R}/repair-environment.rs"),format!("{R}/native-fixed.rs"),binary.into()]{pins.insert(p.clone(),hash(p));}plan["steps"]=json!(steps);plan["source_pins"]=json!(format!("{R}/build-fixed-pins.json"));fs::write(format!("{R}/build-fixed-pins-pre-helper.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(format!("{R}/build-fixed-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Prepared environment-only test repair: 127 OFF successes inherited, only2failedexacttests repeated; ON not yet run; source/flags unchanged; freezer log path only updated");}
